/**
 * Image format identification.
 *
 * A file's extension is a claim, and for images it is frequently wrong: a JPEG
 * saved from a camera may arrive as `.jfif`, a TIFF generated by a scanner as
 * `.tif`, and a renamed `.png` may be a JPEG. The preview therefore identifies
 * the format from its leading bytes and uses the extension only as a hint, so a
 * mislabelled file renders correctly and an undecodable one is explained by the
 * format it actually is.
 */

import type { SdkworkImagePreviewKey } from '../locales.ts'

/** How this preview can treat a format. */
export type ImageDelivery =
  /** The browser decodes it directly, including animation. */
  | 'native'
  /** This package decodes it into pixels itself. */
  | 'decoded'
  /** Gzip-wrapped, so the body inflates it before the browser decodes it. */
  | 'gzip'
  /** Known, but not decodable here; the reader gets an explanation. */
  | 'unsupported'

/** One identified image format. */
export interface ImageFormat {
  /** Short display name, as a reader would say it. */
  readonly name: string
  /** Media type used for the Blob URL, or the empty string when undecodable. */
  readonly mime: string
  readonly delivery: ImageDelivery
  /** Whether the format can carry multiple frames. */
  readonly animatable: boolean
  /**
   * Dictionary key of the sentence shown in place of an undrawable image.
   *
   * A key rather than the sentence: this module identifies bytes, and every
   * word the reader is shown belongs to the locale namespace, which is what
   * keeps an English reader from meeting a Chinese explanation.
   */
  readonly reasonKey?: SdkworkImagePreviewKey
}

/** Formats the browser decodes natively, including their container aliases. */
const NATIVE: Readonly<Record<string, ImageFormat | undefined>> = {
  png: { name: 'PNG', mime: 'image/png', delivery: 'native', animatable: true },
  jpeg: { name: 'JPEG', mime: 'image/jpeg', delivery: 'native', animatable: false },
  gif: { name: 'GIF', mime: 'image/gif', delivery: 'native', animatable: true },
  webp: { name: 'WebP', mime: 'image/webp', delivery: 'native', animatable: true },
  avif: { name: 'AVIF', mime: 'image/avif', delivery: 'native', animatable: true },
  bmp: { name: 'BMP', mime: 'image/bmp', delivery: 'native', animatable: false },
  ico: { name: 'ICO', mime: 'image/x-icon', delivery: 'native', animatable: false },
  svg: { name: 'SVG', mime: 'image/svg+xml', delivery: 'native', animatable: false },
}

/** Formats this package decodes into pixels. */
const DECODED: Readonly<Record<string, ImageFormat | undefined>> = {
  tiff: { name: 'TIFF', mime: 'image/tiff', delivery: 'decoded', animatable: false },
}

/** Formats that arrive gzipped and are inflated before the browser sees them. */
const COMPRESSED: Readonly<Record<string, ImageFormat | undefined>> = {
  svgz: { name: 'SVG', mime: 'image/svg+xml', delivery: 'gzip', animatable: false },
}

